package com.aoo.bcg.common.repair;import java.util.Objects;
/** Repairs the complete club aggregate in one database transaction and validates references before commit. */
public final class ClubReferenceRepairTransaction{public record Request(String repairId,long clubId,long expectedVersion){public Request{if(repairId==null||repairId.isBlank()||clubId<=0||expectedVersion<0)throw new IllegalArgumentException("invalid club repair");}}public interface UnitOfWork{void begin();long lockClubVersion(long clubId);void repairMembers(long clubId);void repairRoles(long clubId);void repairTemplates(long clubId);void repairTables(long clubId);void rebuildStatistics(long clubId);boolean referencesValid(long clubId);long advanceVersion(long clubId,long expectedVersion);void commit();void rollback();}public long execute(Request request,UnitOfWork work){Objects.requireNonNull(request);Objects.requireNonNull(work);work.begin();try{long actual=work.lockClubVersion(request.clubId());if(actual!=request.expectedVersion())throw new VersionedRepairGuard.StaleRepairException(request.expectedVersion(),actual);work.repairMembers(request.clubId());work.repairRoles(request.clubId());work.repairTemplates(request.clubId());work.repairTables(request.clubId());work.rebuildStatistics(request.clubId());if(!work.referencesValid(request.clubId()))throw new IllegalStateException("club aggregate references remain invalid");long next=work.advanceVersion(request.clubId(),actual);if(next<=actual)throw new IllegalStateException("club version did not advance");work.commit();return next;}catch(RuntimeException failure){work.rollback();throw failure;}}}
